// Block (composition) — consumer-controlled notification preference switches.
// Switch and Separator own look/behavior; Stack owns arrangement.
import { Fragment, useId } from "react";
import type { Ref } from "react";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import { Switch } from "../components/Switch";
import "./NotificationPreferences.css";

export interface NotificationPreferencesProps {
  preferences: {
    id: string;
    label: string;
    description?: string;
    enabled?: boolean;
  }[];
  onToggle?: (id: string, enabled: boolean) => void;
  heading?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function NotificationPreferences({
  preferences,
  onToggle,
  heading,
  className,
  ref,
}: NotificationPreferencesProps) {
  const headingId = useId();

  return (
    <Stack
      as="section"
      ref={ref}
      gap="small"
      aria-labelledby={heading ? headingId : undefined}
      aria-label={heading ? undefined : "Notification preferences"}
      className={
        className
          ? `sd-notificationpreferences ${className}`
          : "sd-notificationpreferences"
      }
    >
      {/* The heading labels the section's group of settings (its aria-labelledby), as a field's
          label names its field, so it takes the inset (rule 8). */}
      {heading && (
        <>
          <h2 id={headingId} className="sd-notificationpreferences__heading sd-type-title-medium">
            {heading}
          </h2>
        </>
      )}
      {preferences.map((preference, index) => (
        <Fragment key={preference.id}>
          {index > 0 && <Separator />}
          <Stack
            direction="row"
            justify="between"
            align="center"
            gap="small"
            className="sd-notificationpreferences__row"
          >
            {/* A label and the helper text belonging to it: `switch.field-gap` derives that
                relationship at `2x-small` for the same pair INSIDE the control, and six
                sibling Blocks spend the same rung on it. This row builds the pair itself
                because the settings layout puts the text left and the control right, which
                Switch's own label placement cannot express, but the RUNG is not the Block's
                to re-choose. */}
            <Stack gap="2x-small" className="sd-notificationpreferences__details">
              <span className="sd-notificationpreferences__label sd-type-label-medium">
                {preference.label}
              </span>
              {preference.description && (
                <span className="sd-notificationpreferences__description sd-type-caption-medium">
                  {preference.description}
                </span>
              )}
            </Stack>
            <Switch
              aria-label={preference.label}
              isSelected={Boolean(preference.enabled)}
              onChange={(enabled) => onToggle?.(preference.id, enabled)}
            />
          </Stack>
        </Fragment>
      ))}
    </Stack>
  );
}

/* NotificationPreferences.css — arrangement only; composed Components own all look. */
.sd-notificationpreferences {
  width: 100%;
}

.sd-notificationpreferences__heading {
  margin: 0;
}

.sd-notificationpreferences__row,
.sd-notificationpreferences__details {
  min-width: 0;
}

.sd-notificationpreferences__description {
  color: var(--sd-color-text-muted);
}
